import json,pathlib
rows=[]
def add(id,category,name,subject,body,cta='Take the next step',url='action_url'):
 rows.append(dict(id=id,category=category,name=name,subject=subject,html=f'''<table role="presentation" width="100%" style="background-color:#f3f4fa"><tr><td align="center" style="padding:28px"><table role="presentation" width="100%" style="width:100%;max-width:600px;background-color:#ffffff;font-family:Arial,sans-serif;line-height:1.6"><tr><td style="padding:28px"><img src="{{{{logo_url}}}}" width="200" alt="Zicounsels"><p style="font-size:12px;color:#5865b9">DISPELLING YOUR CLOUDS OF DOUBT</p><h1 style="font-family:Georgia;font-size:28px;color:#23294d">{name}</h1><p>Hello {{{{first_name}}}},</p>{body}<p style="padding:16px"><a href="{{{{{url}}}}}" style="background-color:#515fc1;color:#ffffff;padding:14px;text-decoration:none;border-radius:6px">{cta}</a></p><p>With light,<br>The Zicounsels team</p></td></tr></table></td></tr></table>'''))
add('resource','Growth','Your next step starts here','Your Career Discovery Workbook is ready','<p>You do not have to solve your whole future today. Start with one page of your Career Discovery Workbook: list three strengths, three interests and one question you want help answering.</p><p>Keep your answers. They will give your next career conversation a clearer starting point.</p>','Download my workbook','resource_url')
add('welcome-1','Welcome','A little more clarity, starting today','Welcome to Zicounsels. Here is your first step','<p>Thank you for joining a community built around real people and real career decisions across Africa.</p><p>Set a timer for ten minutes. Write three things you enjoy, three things you are good at, and one thing you would like to try. You already have the beginning of a direction.</p>','Explore Career Clarity Starter','course_url')
add('welcome-2','Welcome','Turn your interests into an experiment','One small experiment for your career this week','<p>Look at the list you made. Choose one interest and test it: speak with someone in that field, try a short lesson or help with a small project.</p><p>Our Career Clarity Starter course gives you a guided way to reflect, explore and choose a practical next step.</p>','Start the course','course_url')
add('welcome-3','Welcome','You do not have to figure it out alone','What actually happens in a counselling session?','<p>A career conversation begins with you: your questions, circumstances and what matters to you. Your counsellor helps you explore options and agree on a practical next step.</p><p>You can review counsellor profiles and available times before booking. There is no promise of an instant answer—just space to think with someone who listens.</p>','Explore counselling','booking_url')
add('welcome-4','Welcome','A real journey, an honest lesson','A career story worth slowing down for','<p>Career paths rarely unfold in a straight line. Safari Zetu makes room for the changes, doubts and decisions behind the polished headlines.</p><p>{{story_excerpt}}</p><p>As you read, ask yourself: which part of this experience speaks to where I am now?</p>','Read the Safari Zetu story','story_url')
add('welcome-5','Welcome','Keep a little clarity close by','Join the conversation beyond your inbox','<p>You have taken a few small steps with us. Keep going at your own pace.</p><p>Our WhatsApp Channel shares practical prompts, programme announcements and opportunities to keep learning. Choose what is helpful for this season of your journey.</p>','Join our WhatsApp Channel','whatsapp_url')
add('nurture','Growth','Feeling stuck is a starting point','One question to ask when your next step feels unclear','<p>Whether you are choosing WAEC or JAMB subjects, searching for a first role or considering a career change, uncertainty can feel heavy.</p><p>Separate what you know from what you need to find out. Write down one unanswered question, then identify one person or reliable source that can help you answer it this week.</p>','Talk it through','booking_url')
add('invite','Webinars','Bring your question. Leave with a next step.','{{event_title}} — your invitation','<p>{{event_promise}}</p><p>Join {{speakers}} on {{event_time}}. Bring your biggest question and something to take notes with.</p><p>When you register, tell us where you are in your career journey so we can make the session useful to you.</p>','Save my place','registration_url')
add('proof','Webinars','Here is why this session matters','One reason to join {{event_title}}','<p>A useful learning experience should leave you able to do something differently.</p><p>{{proof_text}}</p><p>At {{event_title}}, we will work toward this practical outcome: {{event_promise}}.</p>','See the session details','registration_url')
add('reminder-3','Webinars','Three days to your next step','Coming up: {{event_title}}','<p>Our session is getting closer. If this topic has been on your mind, this is a good moment to reserve your place.</p><p>{{event_promise}}</p><p>{{event_time}}. Please check the registration page for current availability.</p>','Check availability','registration_url')
add('logistics','Webinars','Everything you need for tomorrow','Tomorrow: {{event_title}} — joining details','<p>Your session is on {{event_time}}. Your calendar invitation is attached.</p><p>Bring your questions, a notebook and any work you would like to improve. Please join a few minutes early to check your connection.</p>','Open the meeting','meeting_url')
add('three-hours','Webinars','We start in three hours','Three hours to {{event_title}}','<p>Your next career conversation is nearly here. Set aside your notes and check your connection ahead of {{event_time}}.</p><p>If your plans have changed, we understand. We will share the available follow-up resources afterwards.</p>','Find my meeting link','meeting_url')
add('live','Webinars','We are opening the room','Starting shortly: {{event_title}}','<p>We begin in fifteen minutes. Come in, settle down and bring the question you most want answered.</p>','Join the room','meeting_url')
add('replay','Webinars','Keep the learning going','Your {{event_title}} replay and follow-up resources','<p>Thank you for being part of this learning journey. You can revisit the session and find the available certificate and feedback links on the resource page below.</p><p>Choose one idea to put into practice this week. Small action makes the lesson useful.</p>','Open my resources','replay_url')
add('conversion','Webinars','Turn what you learned into a plan','Your next step after {{event_title}}','<p>What stood out during the session? If you would value support applying it to your own circumstances, a counselling conversation can help.</p><p>{{offer_text}}</p>','Explore the counselling offer','booking_url')
add('missed','Webinars','There is still a next step','Missed {{event_title}}? Start here','<p>Life gets busy. You can still explore the available replay and resources, then choose the next step that fits your time.</p><p>You are welcome to join a future session or speak with a counsellor when you are ready.</p>','Catch up here','replay_url')
add('feedback','Webinars','Help us make the next session better','A quick reflection on {{event_title}}','<p>Which part helped you most, and what could we make clearer? Your honest feedback shapes future sessions.</p><p>Tell us one action you plan to take as a result of the session.</p>','Share my feedback','feedback_url')
add('compass','Newsletter','The Compass','The Compass | {{edition}}','<h2>One story</h2><p>{{story_excerpt}}</p><p><a href="{{story_url}}">Read this month’s Safari Zetu story</a></p><h2>One practical tip</h2><p>{{practical_tip}}</p><h2>Your next step</h2><p>{{offer_text}}</p>','Explore this month’s offer','booking_url')
add('academy','Growth','A new way to keep learning','Explore {{course_name}} at the Zicounsels Career Academy','<p>{{course_description}}</p><p>Learn in small steps, try the exercises and bring your questions to the community. Check the course page for access, fees and completion requirements.</p>','Explore the course','course_url')
add('reengage','Retention','Does this still feel useful?','Still interested in career guidance from Zicounsels?','<p>Your priorities may have changed, and that is okay. Let us know which topics are useful to you now.</p><p>If you would rather stop receiving these emails, the unsubscribe link below is always available.</p>','Update my preferences','preferences_url')
add('birthday','Celebrations','A new year of you','Happy birthday, {{first_name}}!','<p>We hope today gives you space to celebrate who you are and the steps you have taken.</p><p>For the year ahead, try one gentle question: what would I like to give myself permission to explore?</p><p>{{birthday_offer}}</p>','Explore my birthday next step','booking_url')
add('anniversary','Celebrations','Here is to your journey','Celebrating your Zicounsels anniversary','<p>Thank you for making Zicounsels part of your journey. Progress is not always loud; sometimes it is a clearer question or the courage to try again.</p><p>{{anniversary_message}}</p>','Choose my next step','booking_url')
add('session-thanks','Retention','Thank you for showing up for yourself','One next step after your counselling session','<p>Take a moment to reflect on the action you chose. Keep your personal notes somewhere private; there is no need to reply with sensitive information.</p>','Share session feedback','feedback_url')
add('session-check','Retention','How is your next step going?','A gentle check-in on your career plan','<p>Were you able to try the action you chose? If circumstances changed, choose a smaller step that fits this week.</p><p>You can book another conversation if you would like support.</p>','Book a follow-up','booking_url')
add('course-reminder','Retention','A little progress is still progress','Continue {{course_name}} when you are ready','<p>Your next lesson is waiting. Set aside ten minutes, revisit your notes and choose one idea to apply.</p>','Continue learning','course_url')
add('application','HR','Thank you for offering your time','We have received your volunteer application','<p>Thank you for your interest in giving one hour a week to support someone’s career journey. Our team will review your application and contact you about the next stage.</p><p>This acknowledgment is not an offer or confirmation of placement.</p>','Review the volunteer journey','volunteer_url')
add('info-session','HR','What could one hour a week make possible?','Your invitation: the Zicounsels volunteer info session','<p>Meet the team and learn about the role, time commitment, screening, support and learning pathway.</p><p>Session time: {{event_time}}. Please check the time in your own location.</p>','Reserve my place','registration_url')
add('interview','HR','Let us get to know each other','Choose a time for your Zicounsels screening conversation','<p>We would like to learn about your experience, areas of competence and approach to supporting people. You will also have time to ask questions about our team and expectations.</p>','Choose an interview time','interview_url')
add('credential','HR','Your next screening step','Conditional next step: credentials and safeguarding checks','<p>We are inviting you to continue the screening process, subject to satisfactory credential verification and the checks relevant to your role.</p><p>Please use the secure portal to provide the documents requested for your qualification or student status. Do not send identity documents or sensitive records by email.</p>','Open the secure verification portal','verification_url')
add('orientation','HR','Welcome to your volunteer cohort','Your Zicounsels orientation details','<p>Welcome to {{cohort_name}}. Your orientation is scheduled for {{event_time}}.</p><p>Your point of contact is {{coordinator_name}}. We will walk through boundaries, systems, supervision and how to ask for help before your first assignment.</p>','View orientation details','orientation_url')
add('crash-course','HR','Build your foundation before you begin','Your Career Counselling Crash Course is ready','<p>Please complete the assigned volunteer crash course and required assessment before progressing to supervised practice.</p><p>Your learning page explains the modules, deadlines and support options. Completion alone is not professional accreditation or authorization to practise independently.</p>','Open my learning pathway','course_url')
add('provision','HR','Your workspace is ready','Set up your Zicounsels account securely','<p>Your approved access invitation is available through our secure portal. Use the link to set up your account and enable the required account protection.</p><p>We will never send passwords or counselling records in a marketing email. If you were not expecting this invitation, contact your coordinator.</p>','Set up my account','provisioning_url')
add('safeguarding','HR','Please review this policy update','Action required: safeguarding and data-handling update','<p>Please read the current approved policy and complete the acknowledgment in the secure portal.</p><p>Keep counselling notes separate from outreach lists. Follow the approved consent and escalation procedures when supporting minors. Refer questions to your safeguarding lead before proceeding.</p>','Read and acknowledge','policy_url')
add('supervision','HR','A space to learn together','Your peer supervision session is coming up','<p>Our next consultation session is {{event_time}}. Please prepare your learning questions and follow the approved process for de-identifying case material.</p><p>Do not reply to this email with client details or clinical notes.</p>','View supervision details','meeting_url')
add('self-care','HR','How are you doing, really?','A check-in for the person behind the support','<p>Thank you for the care you bring to your volunteer work. How manageable is your current commitment?</p><p>If you need a pause, an adjustment or a conversation, please contact your coordinator privately. Sustainable service includes looking after yourself.</p>','Request a private check-in','checkin_url')
add('graduation','HR','Your service matters','Thank you for serving with {{cohort_name}}','<p>Thank you for the time, attention and care you have contributed during your service term.</p><p>Your service acknowledgment and any eligible certificate are available through the link below. We would also value your feedback on the experience.</p>','View my service acknowledgment','certificate_url')
pathlib.Path('zicounsels-mail/public/templates.json').write_text(json.dumps(rows,indent=2))
